#include <stdio.h>

int min(int a, int b) {
    return a < b ? a : b;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int d[65] = {0};
    int e[65] = {0};

    for (int i = 0; i < n; i++) {
        int m;
        char l;
        scanf("%d %c", &m, &l);
        if (l == 'D') {
            d[m]++;
        } else {
            e[m]++;
        }
    }

    int total_pares = 0;
    for (int i = 30; i <= 60; i++) {
        total_pares += min(d[i], e[i]);
    }

    printf("%d\n", total_pares);

    return 0;
}
